<?php
declare(strict_types=1);
namespace Tests\Unit\Services;
use App\Services\DatabaseBackupRoot;use App\Services\DatabaseClientOptionFile;use InvalidArgumentException;use PHPUnit\Framework\TestCase;
final class DatabaseClientOptionFileTest extends TestCase{private string $base;protected function setUp():void{$this->base=sys_get_temp_dir().DIRECTORY_SEPARATOR.'tgh-option-'.bin2hex(random_bytes(5));mkdir($this->base);mkdir($this->base.'\\storage');mkdir($this->base.'\\public');}protected function tearDown():void{$this->rm($this->base);}public function testCreatesEscapedPrivateFileAndCleansUp():void{$file=new DatabaseClientOptionFile(new DatabaseBackupRoot($this->base.'\\storage',$this->base.'\\public'),['host'=>'db','port'=>3306,'username'=>'fake-user','password'=>'fake pass\\";#','charset'=>'utf8mb4'],static fn(int $n):string=>str_repeat("\xAB",$n));$path=$file->path();self::assertFileExists($path);$body=file_get_contents($path);self::assertIsString($body);self::assertSame(1,substr_count($body,'[client]'));self::assertStringContainsString('password="fake pass\\\\\\";#"',$body);$file->cleanup();$file->cleanup();self::assertFileDoesNotExist($path);}public function testRejectsLineInjectionWithoutLeakingSecret():void{try{new DatabaseClientOptionFile(new DatabaseBackupRoot($this->base.'\\storage',$this->base.'\\public'),['host'=>'db','port'=>1,'username'=>'fake-user','password'=>"secret\nuser=x",'charset'=>'utf8mb4']);self::fail();}catch(InvalidArgumentException $e){self::assertSame('Temporary database client configuration failed.',$e->getMessage());self::assertStringNotContainsString('secret',$e->getMessage());}}private function rm(string $p):void{if(is_dir($p)){foreach(scandir($p)?:[]as$n)if($n!=='.'&&$n!=='..')$this->rm($p.'\\'.$n);rmdir($p);}elseif(file_exists($p))unlink($p);}}
